mapper.sql:
is_deleted=0
 AND order_no=#{orderNo}
 AND booker_phone=#{phone}
 AND booker_name LIKE CONCAT('%',#{name},'%')
 AND status=#{status}
 AND planned_checkin_time >= #{arrivalFrom}
 AND planned_checkin_time < DATE_ADD(#{arrivalTo},INTERVAL 1 DAY)
 AND booking_request_id=#{requestId} AND create_by=#{employeeId}
